import{_ as o,a0 as i,w as c,s as r,ao as d,I as n,x as a,a1 as s,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 上使用 Glances 監控系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上使用 Glances 監控系統 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上使用 Glances 監控系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上使用 Glances 監控系統 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151223 How to Use Glances to Monitor System on Ubuntu","title":"如何在 Ubuntu 上使用 Glances 監控系統","tag":"201601","desc":""},"relativePath":"201601/20151223 How to Use Glances to Monitor System on Ubuntu.md","filePath":"[post].md"}'),p={name:"201601/20151223 How to Use Glances to Monitor System on Ubuntu.md"};function u(m,e,h,g,G,b){const l=i("Link");return c(),r("div",null,[e[13]||(e[13]=d(`<h1 id="如何在-ubuntu-上使用-glances-監控系統" tabindex="-1">如何在 Ubuntu 上使用 Glances 監控系統 <a class="header-anchor" href="#如何在-ubuntu-上使用-glances-監控系統" aria-label="Permalink to “如何在 Ubuntu 上使用 Glances 監控系統”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/glances_featured.jpg" alt=""></p><p>Glances 是一個用於監控系統的跨平台、基於文本模式的命令列工具。它是用 Python 編寫的，使用 <code>psutil</code> 庫從系統獲取信息。你可以用它來監控 CPU、平均負載、內存、網絡接口、磁盤 I/O，文件系統空間利用率、掛載的設備、所有活動進程以及消耗資源最多的進程。Glances 有很多有趣的選項。它的主要特性之一是可以在配置文件中設置閥值（careful[小心]、warning[警告]、critical[致命]），然後它會用不同顏色顯示信息以表明系統的瓶頸。</p><h3 id="glances-的功能" tabindex="-1">Glances 的功能 <a class="header-anchor" href="#glances-的功能" aria-label="Permalink to “Glances 的功能”">​</a></h3><ul><li>CPU 平均負載</li><li>不同狀態（如活動、休眠）進程的數量</li><li>所有內存信息，如物理內存、交換空間、空閒內存</li><li>CPU 信息</li><li>網絡連接的上行/下行速度</li><li>磁盤 I/O 讀/寫速度詳細信息</li><li>當前掛載設備的磁盤使用情況</li><li>消耗資源最多的進程和他們的 CPU/內存使用情況</li></ul><h3 id="安裝-glances" tabindex="-1">安裝 Glances <a class="header-anchor" href="#安裝-glances" aria-label="Permalink to “安裝 Glances”">​</a></h3><p>Glances 在 Ubuntu 的軟件倉庫中，所以安裝很簡單。執行下面的命令安裝 Glances：</p><pre><code>sudo apt-get install glances
</code></pre><p>（LCTT 譯註：若安裝後無法正常使用，可考慮使用 pip 安裝/升級 glances：<code>sudo pip install --upgrade glances</code>）</p><h3 id="glances-使用方法" tabindex="-1">Glances 使用方法 <a class="header-anchor" href="#glances-使用方法" aria-label="Permalink to “Glances 使用方法”">​</a></h3><p>安裝完成後，可以執行下面的命令啓動 Glances：</p><pre><code>glances
</code></pre><p>你將看到類似下圖的輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/glances_output1.png" alt="glances monitor system output"></p><p>要退出 Glances 終端，按 ESC 鍵或 <code>Ctrl + C</code>。</p><p>默認情況下，時間間隔（LCTT 譯註：顯示數據刷新的時間間隔）是 1s，不過你可以在從終端啓動 Glances 時自定義時間間隔。</p><p>要把時間間隔設為 5s，執行下面的命令：</p><pre><code>glances -t 5
</code></pre><h3 id="glances-中不同顏色含義" tabindex="-1">Glances 中不同顏色含義 <a class="header-anchor" href="#glances-中不同顏色含義" aria-label="Permalink to “Glances 中不同顏色含義”">​</a></h3><p>Glances 中不同顏色的含義：</p><ul><li><code>綠色</code>：正常（OK）</li><li><code>藍色</code>：小心（careful）</li><li><code>紫色</code>：警告（warning）</li><li><code>紅色</code>：致命（critical）</li></ul><p>默認設置下，Glances 的閥值設置是：careful=50，warning=70，critical=90。你可以通過 “/etc/glances/” 目錄下的默認配置文件 glances.conf 來自定義這些閥值。</p><h3 id="glances-的選項" tabindex="-1">Glances 的選項 <a class="header-anchor" href="#glances-的選項" aria-label="Permalink to “Glances 的選項”">​</a></h3><p>Glances 提供了很多快捷鍵，可以在它運行時用來查找輸出信息。</p><p>下面是一些常用的熱鍵列表：</p><ul><li><code>m</code> : 按內存佔用排序進程</li><li><code>p</code> : 按進程名稱排序進程</li><li><code>c</code> : 按 CPU 佔用率排序進程</li><li><code>i</code> : 按 I/O 頻率排序進程</li><li><code>a</code> : 自動排序進程</li><li><code>d</code> : 顯示/隱藏磁盤 I/O 統計信息</li><li><code>f</code> : 顯示/隱藏文件系統統計信息</li><li><code>s</code> : 顯示/隱藏傳感器統計信息</li><li><code>y</code> : 顯示/隱藏硬盤温度統計信息</li><li><code>l</code> : 顯示/隱藏日誌</li><li><code>n</code> : 顯示/隱藏網絡統計信息</li><li><code>x</code> : 刪除警告和嚴重日誌</li><li><code>h</code> : 顯示/隱藏幫助界面</li><li><code>q</code> : 退出</li><li><code>w</code> : 刪除警告記錄</li></ul><h3 id="使用-glances-監控遠程系統" tabindex="-1">使用 Glances 監控遠程系統 <a class="header-anchor" href="#使用-glances-監控遠程系統" aria-label="Permalink to “使用 Glances 監控遠程系統”">​</a></h3><p>你也可以使用 Glances 監控遠程系統。要在遠程系統上使用它，使用下面的命令：</p><pre><code>glances -s
</code></pre><p>你會看到類似下面的輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/glances_server.png" alt="glances monitor remote system server"></p><p>如你所見，Glances 運行在 61209 端口。</p><p>現在，到遠程機器上執行下面的命令以連接到指定 IP 地址的 Glances 服務器上。假設 192.168.1.10 是你的 Glances 服務器 IP 地址。</p><pre><code>glances -c -P 192.168.1.10
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>對於每個 Linux 系統管理員來説，Glances 都是一個非常有用的工具。使用它，你可以輕鬆、高效地監控 Linux 系統。如果你有什麼問題，自由地評論吧。</p><hr>`,37)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),s(l,{href:"https://www.maketecheasier.com/glances-monitor-system-ubuntu/"},{default:t(()=>[...e[0]||(e[0]=[a("https://www.maketecheasier.com/glances-monitor-system-ubuntu/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=a("作者：",-1)),s(l,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:t(()=>[...e[2]||(e[2]=[a("Hitesh Jethva",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),s(l,{href:"https://github.com/bianjp"},{default:t(()=>[...e[3]||(e[3]=[a("bianjp",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=a("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const C=o(p,[["render",u]]);export{T as __pageData,C as default};
